tool_calls:
cat << 'EOF' > /tmp/merge.awk
# Read defaults first (FILENAME == ARGV[1])
# Then custom (FILENAME == ARGV[2])
BEGIN {
    # We will track sections and keys in order
}

# Match section header
/^[ \t]*\[.*\][ \t]*$/ {
    # Extract section name
    sub(/^[ \t]*\[/, "")
    sub(/\].*$/, "")
    cur_sec = $0
    if (!(cur_sec in sec_seen)) {
        sec_seen[cur_sec] = 1
        sec_list[sec_count++] = cur_sec
    }
    next
}

# Match key=value
/^[ \t]*[^#;=\[\]]+[ \t]*=.*/ {
    if (cur_sec == "") next
    # extract key and value
    eq_pos = index($0, "=")
    k = substr($0, 1, eq_pos - 1)
    v = substr($0, eq_pos + 1)
    # trim key
    sub(/^[ \t]+/, "", k)
    sub(/[ \t]+$/, "", k)

    sec_key = cur_sec SUBSEP k
    if (!(sec_key in key_seen)) {
        key_seen[sec_key] = 1
        keys[cur_sec, key_count[cur_sec]++] = k
    }
    vals[cur_sec, k] = v
    next
}

END {
    for (i = 0; i < sec_count; i++) {
        s = sec_list[i]
        print "[" s "]"
        for (j = 0; j < key_count[s]; j++) {
            k = keys[s, j]
            print k "=" vals[s, k]
        }
        if (i < sec_count - 1) {
            print ""
        }
    }
}
EOF
awk -f /tmp/merge.awk /config/defaults.ini /config/custom.ini

